```dafny
method Power(a: int, n: int) returns (result: int)
  requires n >= 0
  ensures result == PowerSpec(a, n)
{
  result := 1;
  var base := a;
  var exp := n;

  while exp > 0
    invariant result * PowerSpec(base, exp) == PowerSpec(a, n)
    decreases exp
  {
    if exp % 2 == 1 {
      result := result * base;
    }
    base := base * base;
    exp := exp / 2;
  }
}

// Helper function to specify what a^n means mathematically
function PowerSpec(a: int, n: int): int
  requires n >= 0
  decreases n
{
  if n == 0 then 1
  else a * PowerSpec(a, n - 1)
}

// Test cases
method TestPower() {
  var r1 := Power(2, 0);
  assert r1 == 1;

  var r2 := Power(2, 1);
  assert r2 == 2;

  var r3 := Power(2, 3);
  assert r3 == 8;

  var r4 := Power(3, 4);
  assert r4 == 81;

  var r5 := Power(5, 0);
  assert r5 == 1;

  var r6 := Power(1, 100);
  assert r6 == 1;

  print "All tests passed!\n";
}
```

